import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class InventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("InventoryServlet");
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init() throws ServletException {
        dbUrl = System.getenv("JDBC_URL");
        dbUser = System.getenv("DB_USER");
        dbPass = System.getenv("DB_PASS");
    }

    // Parameterized - safe
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String body = req.getReader().lines().reduce("", String::concat);
        JSONObject json = new JSONObject(body);
        String sku = json.getString("sku");
        int qty = json.getInt("quantity");
        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             PreparedStatement ps = conn.prepareStatement(
                 "UPDATE inventory SET quantity = ? WHERE sku = ?")) {
            ps.setInt(1, qty);
            ps.setString(2, sku);
            ps.executeUpdate();
            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"updated\"}");
        } catch (SQLException e) {
            log.severe(e.getMessage());
            resp.sendError(500);
        }
    }

    // Search endpoint - vulnerable to SQL injection via ORDER BY
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");
        if (category == null) { resp.sendError(400); return; }
        if (sortCol == null) sortCol = "name";
        if (sortDir == null) sortDir = "ASC";

        // Developer note: PreparedStatement can't parameterize ORDER BY
        // Using allowlist... but the check has a flaw
        String[] allowedCols = {"name", "sku", "quantity", "price", "updated_at"};
        boolean colValid = false;
        for (String c : allowedCols) {
            if (c.equalsIgnoreCase(sortCol)) { colValid = true; break; }
        }
        // BUG: sortDir is not validated, only sortCol is checked
        if (!colValid) sortCol = "name";

        String sql = "SELECT sku, name, quantity, price, updated_at FROM inventory "
                   + "WHERE category = ? ORDER BY " + sortCol + " " + sortDir;

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, category);
            ResultSet rs = ps.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject item = new JSONObject();
                item.put("sku", rs.getString("sku"));
                item.put("name", rs.getString("name"));
                item.put("quantity", rs.getInt("quantity"));
                item.put("price", rs.getDouble("price"));
                item.put("updated_at", rs.getString("updated_at"));
                results.put(item);
            }
            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            log.warning("Query error: " + e.getMessage());
            resp.sendError(500, "{\"error\":\"query failed\"}");
        }
    }

    // Health check endpoint
    @Override
    protected void doPut(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(200);
        resp.getWriter().write("{\"healthy\":true}");
    }
}
